 hdr=b[hstart:end]; print('\nblock',n,'off',o,'raw',raw,'hdr_size',hdr_size,'crc ok',hex(zlib.crc32(hdr)&0xffffffff))
 p=o+4+l; hid,hl=rv(b,p); p+=hl; flags,fl=rv(b,p); p+=fl; print('id flags',hid,hex(flags),'p_rel',p-o)
 ds=0
 if hid==1:
  ed=0
  if flags&1: ed,el=rv(b,p); p+=el; print('ed',ed)
  af,al=rv(b,p); p+=al; print('af',af,'extra',b[p:end].hex())
 elif hid in (2,3):
  ed=0
  if flags&1: ed,el=rv(b,p); p+=el; print('ed',ed,'edlen',el)
  if flags&2: ds,dl=rv(b,p); p+=dl; print('ds',ds)
  file_flags,vl=rv(b,p); p+=vl
  unpacked,vl=rv(b,p); p+=vl
  attr,vl=rv(b,p); p+=vl
  mtime=crc32=None
  if file_flags&2: mtime=b[p:p+4]; p+=4
  if file_flags&4: crc32=b[p:p+4]; p+=4
  comp,vl=rv(b,p); p+=vl
  host,vl=rv(b,p); p+=vl
  ns,vl=rv(b,p); p+=vl
  name=b[p:p+ns]; p+=ns
  print('ff/unp/attr/mtime/crc/comp/host/name',file_flags,unpacked,attr,mtime.hex() if mtime else None,crc32.hex() if crc32 else None,comp,host,name)
  print('extra starts rel',p-o,'end rel',end-o,'bytes',b[p:end].hex())
  q=p
  while q<end:
   fs,fsl=rv(b,q); q+=fsl; fid,fil=rv(b,q); q+=fil
   print(' field size',fs,'id',fid,'start rel',q-o,'rembytes',b[q:end].hex())
   if fid==6:
    flags2,vl=rv(b,q); q+=vl; print('  owner flags',flags2)
    if flags2&1:
     ln,vl=rv(b,q); q+=vl; print('  uname len',ln,'data',b[q:q+min(ln,20)]); q+=ln
    if flags2&2:
     ln,vl=rv(b,q); q+=vl; print('  gname len',ln,'data',b[q:q+min(ln,20)]); q+=ln
    if flags2&4:
     idv,vl=rv(b,q); q+=vl; print('  uid',idv)
    if flags2&8:
     idv,vl=rv(b,q); q+=vl; print('  gid',idv)
   else: q+=fs
 o=end+ds; n+=1
